1	"use client";
2	
3	import * as React from "react";
4	import { useTransition } from "react";
5	import Link from "next/link";
6	import { Phone, CalendarClock, X, Check } from "lucide-react";
7	import { Card } from "@/components/ui/Card";
8	import { Button } from "@/components/ui/Button";
9	import { Field, Input } from "@/components/ui/Field";
10	import { StatusBadge } from "@/components/ui/StatusBadge";
11	import { cancelBooking, rescheduleBooking } from "@/app/(customer)/account/actions";
12	import { t } from "@/lib/i18n";
13	import { useToast } from "@/components/ui/Toast";
14	
15	export interface UpcomingItem {
16	  id: string;
17	  providerName: string;
18	  blockMinutes: number;
19	  whenLabel: string;
20	}
21	
22	export function UpcomingBookings({ items }: { items: UpcomingItem[] }) {
23	  const [pending, startTransition] = useTransition();
24	  const [rescheduleId, setRescheduleId] = React.useState<string | null>(null);
25	  const [newTime, setNewTime] = React.useState("");
26	  const { announce, toast } = useToast();
27	
28	  function cancel(id: string) {
29	    startTransition(async () => {
30	      const res = await cancelBooking(id);
31	      if (!res.ok) {
32	        toast(res.error ?? t("booking.error"), "alert");
33	        return;
34	      }
35	      announce(
36	        res.released ? t("account.cancelledRefund") : t("account.cancelledCharged"),
37	        true,
38	      );
39	    });
40	  }
41	
42	  function saveReschedule(id: string) {
43	    if (!newTime) return;
44	    startTransition(async () => {
45	      const res = await rescheduleBooking({
46	        bookingId: id,
47	        scheduledAt: new Date(newTime).toISOString(),
48	      });
49	      if (!res.ok) {
50	        toast(res.error ?? t("booking.error"), "alert");
51	        return;
52	      }
53	      setRescheduleId(null);
54	      setNewTime("");
55	      announce(t("account.nextSession"));
56	    });
57	  }
58	
59	  if (items.length === 0) {
60	    return (
61	      <Card>
62	        <p className="text-base text-ink-soft">{t("account.upcomingNone")}</p>
63	      </Card>
64	    );
65	  }
66	
67	  return (
68	    <ul className="flex flex-col gap-3">
69	      {items.map((item) => (
70	        <Card as="li" key={item.id} className="flex flex-col gap-3">
71	          <div className="flex flex-wrap items-center justify-between gap-3">
72	            <div className="flex items-center gap-3">
73	              <StatusBadge tone="info" icon={CalendarClock}>
74	                {item.whenLabel}
75	              </StatusBadge>
76	              <span className="text-base font-bold text-ink">
77	                {item.providerName} · {item.blockMinutes} min
78	              </span>
79	            </div>
80	            <div className="flex flex-wrap items-center gap-2">
81	              <Link href={`/session/${item.id}`} className="rounded-btn">
82	                <Button icon={Phone}>{t("account.join")}</Button>
83	              </Link>
84	              <Button
85	                variant="ghost"
86	                icon={CalendarClock}
87	                onClick={() =>
88	                  setRescheduleId(rescheduleId === item.id ? null : item.id)
89	                }
90	              >
91	                {t("account.reschedule")}
92	              </Button>
93	              <Button
94	                variant="ghost"
95	                icon={X}
96	                onClick={() => cancel(item.id)}
97	                disabled={pending}
98	              >
99	                {t("account.cancel")}
100	              </Button>
101	            </div>
102	          </div>
103	
104	          {rescheduleId === item.id ? (
105	            <div className="flex flex-wrap items-end gap-3 border-t border-border pt-3">
106	              <Field label={t("account.rescheduleHeading")}>
107	                {(p) => (
108	                  <Input
109	                    {...p}
110	                    type="datetime-local"
111	                    value={newTime}
112	                    onChange={(e) => setNewTime(e.target.value)}
113	                  />
114	                )}
115	              </Field>
116	              <Button
117	                icon={Check}
118	                onClick={() => saveReschedule(item.id)}
119	                disabled={pending || !newTime}
120	              >
121	                {t("account.rescheduleSave")}
122	              </Button>
123	            </div>
124	          ) : null}
125	        </Card>
126	      ))}
127	    </ul>
128	  );
129	}
